function studioEnvironment(renderer){const room=new THREE.Scene();room.background=new THREE.Color('#b6b6b6');for(const [w,h,x,y,z,rx,ry,strength] of [[16,12,0,10,0,-Math.PI/2,0,3],[8,10,-10,4,2,0,Math.PI/2,2],[10,8,8,4,-7,0,-.6,1.8]]){const card=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({color:new THREE.Color().setScalar(strength),side:THREE.DoubleSide}));card.position.set(x,y,z);card.rotation.set(rx,ry,0);room.add(card);}const pmrem=new THREE.PMREMGenerator(renderer),target=pmrem.fromScene(room,.08);room.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});pmrem.dispose();return target;}
