this.addToolbar();this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(this.stage);this.stage.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const p=this.camera.position;const offset=p.clone().sub(this.controls.target),sph=new THREE.Spherical().setFromVector3(offset);if(e.key==='ArrowLeft')sph.theta-=.12;if(e.key==='ArrowRight')sph.theta+=.12;if(e.key==='ArrowUp')sph.phi=Math.max(.1,sph.phi-.1);if(e.key==='ArrowDown')sph.phi=Math.min(1.4,sph.phi+.1);p.copy(new THREE.Vector3().setFromSpherical(sph).add(this.controls.target));this.controls.update();this.draw();}});
